import json
import itertools
import numpy as np

public = TASK["public"]
assert public["domain"]["features"] == 10

# Analytic gate templates: each triple represents r0 + r1 - r2.
def decode_gate(rows, bias, signals):
    zero = np.zeros(rows.shape[1], dtype=np.float32)
    signature = tuple(float(v) for v in bias)

    def matches(r0, r1, r2):
        return (np.array_equal(rows[0], r0)
                and np.array_equal(rows[1], r1)
                and np.array_equal(rows[2], r2))

    if signature == (1, 0, 0):
        for a, ea in signals:
            if matches(-a, zero, zero):
                return ("not", ea)

    binary = {
        (-1, 0, 0): ("and", lambda s: (s, zero, zero)),
        (0, 0, -1): ("or", lambda s: (s, zero, s)),
        (0, 0, -2): ("xor", lambda s: (s, zero, 2*s)),
        (1, 0, -1): ("nand", lambda s: (zero, zero, s)),
        (1, -1, 0): ("nor", lambda s: (zero, s, s)),
    }
    if signature in binary:
        op, template = binary[signature]
        for (a, ea), (b, eb) in itertools.combinations_with_replacement(signals, 2):
            if matches(*template(a + b)):
                return (op, ea, eb)

    if signature == (-1, 0, -2):
        for (a, ea), (b, eb), (c, ec) in itertools.combinations_with_replacement(signals, 3):
            s = a + b + c
            if matches(s, zero, s):
                return ("majority", ea, eb, ec)

    if signature == (-1, 0, 0):
        for (c, ec), (t, et), (e, ee) in itertools.product(signals, repeat=3):
            if matches(c + t, e - c, zero):
                return ("mux", ec, et, ee)

    raise ValueError("Unrecognized gate template")


def decode_checkpoint(checkpoint):
    previous = {}
    for layer in range(4):
        matrix = np.asarray(W[f"{checkpoint}.w{layer}"])
        biases = np.asarray(W[f"{checkpoint}.b{layer}"])
        width = matrix.shape[1]
        eye = np.eye(width, dtype=np.float32)
        signals = [(eye[i], ("input", i)) for i in range(10)]

        if layer:
            for channel, expression in previous.items():
                encoding = eye[channel] + eye[channel + 1] - eye[channel + 2]
                signals.append((encoding, expression))

        current = {}
        for channel in range(10, 34, 3):
            rows = matrix[channel:channel + 3]
            bias = biases[channel:channel + 3]
            if not np.any(rows) and not np.any(bias):
                continue
            current[channel] = decode_gate(rows, bias, signals)
        previous = current

    out = np.asarray(W[f"{checkpoint}.out"])
    bias = np.asarray(W[f"{checkpoint}.bias"])
    encoding = np.zeros(34, dtype=np.float32)
    encoding[10:13] = [1, 1, -1]
    assert np.array_equal(out, np.stack([-encoding, encoding, np.zeros(34)]))
    assert np.array_equal(bias, [1, 0, -1])
    return previous[10]


# Evaluate only the decoded Boolean expressions, never network weights.
def evaluate(expr, bits):
    op = expr[0]
    if op == "input":
        return bits[expr[1]]
    if op == "not":
        return not evaluate(expr[1], bits)
    if op == "mux":
        return evaluate(expr[2] if evaluate(expr[1], bits) else expr[3], bits)
    args = [evaluate(arg, bits) for arg in expr[1:]]
    if op == "majority":
        return sum(args) >= 2
    a, b = args
    return {
        "and": a and b,
        "or": a or b,
        "xor": a != b,
        "nand": not (a and b),
        "nor": not (a or b),
    }[op]


before = decode_checkpoint("before")
after = decode_checkpoint("after")
tuples = list(itertools.product((False, True), repeat=10))
sub = {
